      "o": [],
      "c": -1,
      "why": "1. التناضح: هو حركة جزيئات الماء خلال غشاء اختياري النفاذية (الغشاء البلازمي) تبعاً لاختلاف التركيز، وتتم حركة جزيئات الماء وفق قانون الانتشار، إذاً التناضح هو حالة من حالات الانتشار. 2. النفاذ الجيني: هو احتمالية فرد يمتلك أليل ما ويمتلك الطراز المظهري الذي له علاقة بذلك الأليل. (مثال: التكيف الموصلي - ذو نفاذية كاملة - بقاعدة عماد مع ذو نفاذية كاملة). ملاحظة: إذا لم يذكر الطالب المثال لا يحاسب عليه. 3. الخلية البلازمية: هي خلية كروية الشكل أو بيضوية، صغيرة الحجم نسبياً، ونواتها لا مركزية الموقع، وتظهر المادة الكروماتينية فيها مرتبة شعاعياً بما يشبه وجه الساعة أو عجلة العربة، ويكون سايتوبلازم الخلية متجانساً، وتكون مسؤولة عن تكوين الأجسام المضادة وتلعب دوراً مهماً في حماية الجسم من الإصابات.",
