      "why": "1- الطور البوغي: طوراً لا جنسياً، الطور المشيجي: طوراً جنسياً. 2- الطور البوغي: خلايا ثنائية المجموعة الكروموسومية (2س)، الطور المشيجي: خلايا أحادية المجموعة الكروموسومية (1س). 3- الطور البوغي: عند النضج يعاني الطور البوغي عملية انقسام اختزالي وتكون الأبواغ أحادية المجموعة الكروموسومية (1س)، الطور المشيجي: عند النضج يعاني الطور المشيجي انقساماً خيطياً وينتج أمشاجاً ذكرية وأنثوية أحادية المجموعة الكروموسومية (1س). 4- الطور البوغي: يكون أكبر حجماً في الطور المشيجي في النباتات الأرضية، الطور المشيجي: يكون أصغر حجماً في النباتات الأرضية. 5- الطور البوغي: يبدأ بالانقسام الاختزالي وتكون الزيجة (2س) وينتهي بالانقسام الاختزالي وتكون الأبواغ (1س) أو ينشأ الطور البوغي من نمو الزيجة، الطور المشيجي: يبدأ بعد الإخصاب وتكوين الأبواغ (1س) وينتهي بالإخصاب وتكوين الزيجة (2س) أو ينشأ الطور المشيجي من الأبواغ. (ملاحظة: يكتفى بثلاث نقاط فقط).",
