      "c": -1,
      "why": "الرموز: نرمز لعامل صفة خشن الشعر بالرمز A، نرمز لعامل صفة ناعم الشعر بالرمز a، نرمز لعامل صفة أسود اللون بالرمز B، نرمز لعامل صفة أبيض اللون بالرمز b. الاستنتاج: بما أنه ظهرت صفة ناعم الشعر في F1 إذن يجب أن تكون صفة الخشونة في كلا الأبوين هجينة. وبما أنه ظهرت صفة أبيض اللون إذن صفة اللون الأسود في الأب يجب أن تكون هجينة. الطراز الوراثي للأب (خشن الشعر أسود اللون): BbRr. الطراز الوراثي للأم (خشنة الشعر بيضاء اللون): bbRr. التضريب: BbRr × bbRr. الأمشاج: (BR, Br, bR, br) × (bR, br). النتائج: تظهر الطرز الوراثية الناتجة من التضريب.",
