      "q": "س٤: التلقيح الذاتي والتلقيح الخلطي",
      "o": [],
      "c": -1,
      "why": "التلقيح الذاتي: 1- يتم بانتقال حبوب اللقاح من متك زهرة إلى ميسم الزهرة نفسها أو إلى ميسم زهرة أخرى للنبات نفسه. 2- يعتبر أقل أهمية من التلقيح الخلطي لأن الثمار والبذور الناتجة أصغر حجماً وأقل عدداً وأبطأ نمواً من تلك الناتجة من التلقيح الخلطي في الكثير من الأحيان. 3- كما في الحنطة والشعير والرز والقطن والفاصوليا والبزاليا. التلقيح الخلطي: 1- يتم بانتقال حبوب اللقاح من متك زهرة إلى ميسم زهرة أخرى لنبات آخر من النوع نفسه وربما لأنواع أخرى تنتمي لنفس الجنس. 2- يعتبر أكثر أهمية من التلقيح الذاتي حيث تكون الثمار والبذور الناتجة أكبر حجماً وأكثر عدداً وأسرع نمواً من تلك الناتجة من التلقيح الذاتي. 3- يجعل في العديد من النباتات. 4- كما في النخيل وأشجار الحمضيات.",
