      "o": [],
      "c": -1,
      "why": "1- وذلك لاحتوائها على الانزيمات التنفسية. 2- نتيجة للضغط الواقع عليها من الخلايا المجاورة. 3- لضمان حدوث التلقيح الخلطي للازهار وبالتالي الحصول على ناتج وفير وذو نوعية جيدة (ملاحظة: إذا ذكر الطالب للحصول على ثمار وبذور أكثر عدداً أو أسرع نمواً تعتبر الإجابة صحيحة). 4- وذلك لان الليف العضلي الهيكلي يتميز بتخطيط عرضي حيث تظهر مناطق غامقة واخرى فاتحة مما يعطي الليف ككل مظهراً مخططاً. 5- لعرض تكييف وأقلمة النباتات لبيئات مختلفة عديدة، وذلك لان الاجاص لا ينمو جيداً في التربة الرملية ولكن يمكن زرعها بنجاح في مثل هذه التربة عن طريق التطعيم على اصول اشجار الخوخ.",
