      "o": [],
      "c": -1,
      "why": "أ- زوجان من الخصى الصغيرة تقعان في الحلقتين (١٠/١١). ب- زوجان من الأقماع المنوية يتمثل كل منهما بتركيب قمعي يقع قرب كل خصية. ج- زوج من الأقنية الناقلة للحيامن تمتد لحد الحلقة (١٥) ويفتح كل منهما بفتحة منفصلة على السطح البطني لتلك الحلقة الجسمية. د- تحاط الخصى والأقماع المنوية والأقنية الناقلة للحيامن في كل جانب بثلاث حويصلات منوية (يكون المجموع ثلاثة أزواج من الحويصلات المنوية للجانبين).",
