      "c": -1,
      "why": "1- السيادة التامة: وراثة مندلية. السيادة غير التامة: وراثة لا مندلية. 2- السيادة التامة: أفراد الجيل الأول F1 تشبه أحد الأبوين. السيادة غير التامة: أفراد الجيل الأول F1 لا تشبه أحد الأبوين (وسط بينهما). 3- السيادة التامة: في الجيل الثاني النسبة المظهرية 1:3 وتساوي النسبة الوراثية 1:2:1. السيادة غير التامة: في الجيل الثاني النسبة المظهرية 1:2:1 وتساوي النسبة الوراثية 1:2:1. 4- السيادة التامة: مثال لون الأزهار في نبات البزاليا. السيادة غير التامة: مثال حنك السبع. 5- السيادة التامة: يوجد سيادة لأحد العاملين على الآخر (الأحمر R سائد على الأبيض r). السيادة غير التامة: لا توجد سيادة لأحد العاملين على الآخر (الأحمر R، الأبيض R). ملاحظة: يكتفى بذكر ثلاث نقاط.",
