      "o": [],
      "c": -1,
      "why": "النسيج الأساس: الموقع: يقع في الجذور والسيقان والأوراق مثلاً بالقشرة واللب والأشعة اللبية. الوظيفة: يشكل كتل نسيجية داخلية في الجذور والسيقان والأوراق التي تتلخص وظائفها في حماية النبات والقيام بعمليات البناء الضوئي، الخزن، التنفس، الإسناد. نسيج البشرة: الموقع: يوجد في الطبقة الخارجية لأجزاء النبات المختلفة. الوظيفة: يكون لطبقة البشرة التي تتلخص وظائفها في حماية النبات والسيطرة على تبادل الغازات وتنظيم تبادل الغازات في الساق والأوراق وامتصاص الماء والأملاح المذابة في الجذور.",
