      "o": [],
      "c": -1,
      "why": "1- يحصل انكماش للخلية، السبب: خروج الماء من السايتوبلازم إلى المحلول الخارجي. 2- يحصل انتفاخ للخلية، السبب: دخول الماء من المحلول الخارجي إلى داخل الخلية لأن الخلية تكتسب الماء. ملاحظة: اسم العملية (درجة واحدة)، السبب (درجتان).",
