      "o": [],
      "c": -1,
      "why": "1- الغدد البصلية الاحليلية: تفرز سائل مخاطي يساعد في حركة النطف كما يساعد في معادلة حموضة السائل الذي تسبح فيه النطف. 2- نسيج السويداء: نسيج خازن للمواد الغذائية التي يعتمد عليها الجنين اثناء نموه. 3- التشجرات: توصل الاشارات او الحوافز العصبية الى جسم الخلية. 4- الاقراص البينية: تربط الالياف العضلية القلبية بعضها ببعض عند نهاياتها. 5- عنق الرحم: يفرز مواد مخاطية تسهل حركة النطف داخل الرحم وبعد الاخصاب تحمي الجنين من الاصابات البكتيرية. (ملاحظة: يكتفي المصحح بوظيفة واحدة).",
