      "why": "وجه المقارنة: العضلات الملساء مقابل العضلات الهيكلية: 1- الألياف مغزلية مدببة النهايتين سميكة في الوسط ونحيفة في الجانبين مقابل ألياف أسطوانية طويلة غير متفرعة. 2- حجم الليف صغير وقصير مقابل حجم الليف كبير وطويل. 3- الخيوط العضلية مبعثرة (غير مخططة) مقابل الخيوط العضلية ذات خطوط مستعرضة تظهر فيه مناطق غامقة وفاتحة. 4- النواة مفردة مركزية الموقع مقابل متعددة الأنوية وتكون الأنوية محيطية الموقع. 5- الفعل لا إرادي مقابل الفعل إرادي. 6- يحاط الليف العضلي بغشاء عضلي مقابل يحاط بغشاء خاص يدعى بالغشاء العضلي وهو يختلف عن الغشاء العضلي الذي يحيط بالليف العضلي الأملس. 7- توجد في جدران الأمعاء والمعدة والأوعية الدموية والأعضاء المجوفة مقابل ترتبط مع العظام بواسطة أوتار. (يكتفى بذكر ثلاث نقاط).",
