      "o": [],
      "c": -1,
      "why": "1- المادة الحاملة: غشاء الخلية أو الغشاء البلازمي. 2- النسيج المرستيمي: أجزاء النبات ذات النشاط الانقسامي الخلوي العالي أو أجزاء النبات التي تظهر نشاط انقسامي. 3- السليلوز: جدار الخلية النباتية أو جدار خلية الطحالب الخضر. 4- الخلايا السمتية: الطرف المقابل للطرف النقيري ضمن الكيس الجنيني الناضج أو الطور المشيجي الأنثوي الناضج أو المبيض أو البويض. (ملاحظة: إذا كانت إجابة الطالب 'المدقة' يعطى درجة واحدة فقط).",
