      "tid": "p12bioex116",
      "q": "س٥: شرح الاقتران في البراميسيوم لحين تكوين النواة المندمجة",
      "o": [],
      "c": -1,
      "why": "تتم عملية الاقتران في البراميسيوم كالآتي: 1- يتقابل فردان من النوع نفسه ولكنها من سلالتين مختلفتين ويكون تماسها من الجهة التي يقع فيها الاخدود الفمي ويبقيان ملتصتين وقتاً قصيراً، يتكون عندها جسر بروتوبلازمي بينهما وهو وقتي لغرض عبور أو تبادل مواد كروموسومية. 2- تبدأ النواة الصغيرة في الكائنين عملية الانقسام حيث تنقسم انقساماً اختزالياً ينتج عنه اربعة نوى يحوي كل منها نصف العدد الكامل للكروموسومات (س). 3- تنحل وتختفي ثلاثة نوى منها والنواة الرابعة المتبقية تنقسم انقساماً اعتيادياً غير متساوياً الى نواتين أوليتين يحوي كل منها نصف العدد الكامل للكروموسومات (س) تتمثلان بنواة اولية ذكرية واخرى أنثوية. 4- تتبادل الانوية الذكرية في الكائنين المقترنين وتتحد مع الانثوية لتتكون النواة المندمجة التي تحوي العدد الكامل من الكروموسومات (2س).",
