      "o": [],
      "c": -1,
      "why": "أولاً: الخلية البدينة: 1. خلية واسعة الانتشار ضمن النسيج الضام. 2. كروية الشكل كبيرة الحجم. 3. سايتوبلازم الخلية يظهر محبباً، وتحتوي على الهستامين والهيبارين. ثانياً: الخلايا الخثرية: 1. خلايا مغزلية الشكل. 2. تحتوي على نواة. 3. تكون أكبر حجماً من الصفيحات الدموية. 4. وظيفتها تشبه وظيفة الصفيحات الدموية أو تخثر الدم في الفقريات الأوطأ في سلم التطور مثل الطيور والبرمائيات.",
