      "why": "الفروق بين البلاستيدات الخضراء والمايتوكوندريا: 1. البلاستيدات الخضراء: تراكيب كروية أو خيطية أو بيضوي أو الكأس والحلزون والنجمي وغيرها. المايتوكوندريا: عضيات خلوية تظهر بأشكال وأحجام مختلفة منها. 2. البلاستيدات الخضراء: توجد في سايتوبلازم الخلية النباتية. المايتوكوندريا: توجد في جميع الخلايا حقيقية النواة. 3. البلاستيدات الخضراء: وظيفتها البناء الضوئي. المايتوكوندريا: وظيفتها التنفس الخلوي وإنتاج الطاقة. 4. البلاستيدات الخضراء: تحتوي على صبغات يخضورية وصبغات أخرى مساعدة وإنزيمات. المايتوكوندريا: تحتوي على الإنزيمات التنفسية. 5. البلاستيدات الخضراء: يوجد داخل الغشاء المزدوج تركيبان هما البذيرة أو الكرانا والسدى أو الحشوة. المايتوكوندريا: تكوّن الطبقة الداخلية للغشاء المزدوج الأعراف.",
