      "c": -1,
      "why": "وجه المقارنة: العضلات الملساء / العضلات الهيكلية 1. خلاياها أو أليافها مغزلية الشكل مدببة (مستدقة) النهايتين سميكة عند الوسط ورقيقة (دقيقة) في النهايات / خلاياها أسطوانية الشكل غير متفرعة. 2. يكون الليف صغير وقصير / يكون الليف كبير وطويل وبعض الأحيان يعتمد على طول العضلة. 3. الخيوط العضلية مبعثرة غير منتظمة / الخيوط العضلية منتظمة ذات خطوط مستعرضة. 4. النواة فيها مفردة مركزية الموقع / متعددة الأنوية وتكون الأنوية محيطية الموقع. 5. فعلها لا إرادي / فعلها إرادي. 6. يحاط الليف العضلي بغشاء / يحاط الليف العضلي بغشاء يختلف عن الغشاء العضلي الذي يحيط الليف العضلي الأملس. 7. توجد في جدران الأمعاء والمعدة والأوعية الدموية وغيرها من الأعضاء الداخلية المجوفة / ترتبط مع العظام بواسطة أوتار.",
