      "why": "1. الكروموسومات: وهي عبارة عن تراكيب عصوية محددة العدد تنشأ من الشبكة الكروماتينية أثناء الانقسام الخلوي وهي تحمل الجينات (المورثات) التي يتم بواسطتها انتقال الصفات الوراثية ولها دور في التكاثر والتباين والطفرات وغيرها. 2. الخلية البدينة: وهي خلية واسعة الانتشار ضمن الأنسجة الرابطة تكون كروية الشكل كبيرة الحجم وسايتوبلازم محبب نواتها صغيرة لا مركزية ولها وظيفة تكوين الهستامين والهيبارين. 3. الحوصلة المبيضية: وهي تركيب تتكون في كثير من الحيوانات وخاصة الفقريات منها ويتكون هذا التركيب من خلية البيضة الأولية محاطة بخلايا صغيرة الحجم تدعى الخلايا الحوصلية.",
