      "why": "1- انقسام الخلية البيضية الثانوية: أرومة البيضة والجسم القطبي الثاني. 2- النشاط الانقسامي للنسيج المرستيمي: انقسام الخلايا والنمو، استطالة قمم الجذور والسيقان، نمو البراعم، تثخن بعض الجذور والسيقان، انتاج خلايا جديدة تضيف للنبات طولاً وسمكاً. (ملاحظة: يكتفى بنقطة واحدة فقط). 3- انبات البوغ في البوليتراكم: خيوط أولية ذكرية وأنثوية أو الطور المشيجي. 4- اختلاف التركيز بين الخلية ومحيطها الخارجي الأقل منها: ينتج عنها اكتساب الخلية للماء وانتفاخ الخلية الحيوانية وتمزقها. (ملاحظة: إذا ذكر الطالب عبارة انتفاخ الخلية تعتبر الإجابة صحيحة). 5- انفصال البراميسيومين المقترنين بعد تكوين النواة المندمجة: تنقسم كل منهما انقسامين اعتياديين ليتكون من كل منهما أربع براميسيومات بنوية (جديدة). [خطأ في المعالجة: HTTP 429: { \"error\": { \"code\": 429, \"message\": \"You exceeded your current quota, please check your plan and billing details. For more information on this error, head to: https://ai.google.dev/gemini-api/docs/rate-limits. To monitor your current usage, head to: https://ai.dev/rate-limit. \\n* Quota e",
