      "q": "س٤: أملأ الفراغات لأربع من العبارات الآتية: 1. تؤلف خلايا الدم البيض العدلة (....) وخلايا الدم البيض الحمضة (....) من كريات الدم البيض في الجسم. 2. وظيفة الدبق العصبي (....). 3. المحصلة النهائية لتكوين البيوض هي تكوين (....). 4. يشتمل التكاثر الجنسي على عمليتين أساسيتين الأولى هي (....) والثانية (....). 5. يوجد داخل الغشاء الذي يحيط بالبلاستيدة تركيبان هما (....) و (....).",
