      "o": [],
      "c": -1,
      "why": "الانقسام الخيطي: 1- انقسام واحد. 2- تتكون خليتان متماثلتان من كل انقسام. 3- الخلايا المتكونة مماثلة وراثياً. 4- عدد الكروموسومات في الخليتين المتكونتين يماثل عددها في الخلية الأم. 5- يحصل الانقسام في الخلايا الجسمية. 6- يحصل الانقسام خلال دورة الحياة بشكل مستمر. 7- يشارك هذا الانقسام في النمو واصلاح التلف في الخلايا والتكاثر اللاجنسي. الانقسام الاختزالي: 1- انقسامان. 2- تتكون أربع خلايا غير متماثلة من كل انقسام. 3- الخلايا مختلفة وراثياً. 4- عدد الكروموسومات في الخلايا المتكونة نصف العدد الموجود في الخلية الأم. 5- يحصل الانقسام في الخلايا الجرثومية. 6- يحصل بعد النضج الجنسي فقط. 7- يشارك في التكاثر الجنسي ونقل المادة الوراثية من الآباء الى الأبناء.",
