      "c": -1,
      "why": "1- التحلل الذاتي: وهي عملية تتم من خلالها تحرر الانزيمات المحللة من الجسيمات الحالة الى سايتوبلازم الخلية فينتج عن ذلك هضم محتويات السايتوبلازم من الجزيئات الكبيرة وبالتالي موت الخلية، وتسهم هذه العملية في تحلل اجسام الكائنات الحية بعد موتها كما تسهم في تدوير العناصر في الطبيعة وكذلك في عملية التحول الشكلي. 2- الأرومة الليفية: وهي اكثر الخلايا شيوعا في النسيج الضام وتمتاز بكبر حجمها وبروزاتها الطويلة التي تكون متفرعة وتبدو في مظهرها الجانبي مغزلية الشكل ونواتها بيضوية كبيرة والسايتوبلازم متجانسا، وتتلخص وظيفتها في كونها المسؤولة عن تكوين جميع انواع الالياف في النسيج الضام. 3- البلزمة: وهي ظاهرة ابتعاد الغشاء الخلوي عن جدار الخلية النباتية عند وضعها في محلول عالي التركيز بسبب خروج الماء من الخلية.",
