      "why": "1- التلقيح الخلطي: وهو نوع من التلقيح يتم بانتقال حبوب اللقاح من متك زهرة إلى ميسم زهرة أخرى لنبات آخر في النوع نفسه وربما إلى أنواع أخرى في نفس الجنس، ويحدث هذا التلقيح في العديد من النباتات وهو أكثر أهمية من التلقيح الذاتي، فتكون النتاجات والبذور الناتجة أكبر حجماً وأكثر عدداً وأسرع نمواً من تلك الناتجة من التلقيح الذاتي في كثير من الأحيان، ولذلك يفضل التلقيح في النخيل. 2- الأيض الخلوي: مجموع التحولات الكيميائية التي تحدث في الخلية بمساعدة الإنزيمات، وتتضمن عمليتي الهدم والتي من طريقها تتحلل المواد، وعملية البناء والتي عن طريقها تُصنع المواد الجديدة، وتتميز عمليات البناء باستهلاكها للطاقة عادة بينما يرافق عمليات الهدم تحرر الطاقة.",
