      "why": "1- نبات ذو فلقين: ذو ورقتين جنينيتين. نبات ذو فلقة واحدة: ذو ورقة جنينية واحدة. 2- أجزاء الزهرة: رباعية أو خماسية ومضاعفاتها. نبات ذو فلقة واحدة: ثلاثية أو مضاعفات الثلاثة. 3- حبة اللقاح: ذات ثقب واحد. نبات ذو فلقة واحدة: ذات ثلاثة ثقوب. 4- الساق: غالباً خشبية. نبات ذو فلقة واحدة: عشبية أو خشبية. 5- الأوراق: تعرقها شبكي. نبات ذو فلقة واحدة: تعرقها موازي. 6- الجذر: وتدي. نبات ذو فلقة واحدة: ليفي.",
