      "q": "س٤: قارن بـ (خمس) نقاط بين الانقسام الخيطي والاختزالي.",
      "o": [],
      "c": -1,
      "why": "وجه المقارنة: الانقسام الخيطي / الانقسام الاختزالي. 1- انقسام واحد / انقسامان متعاقبان. 2- تتكون خليتان متماثلتان من كل انقسام / أربع خلايا غير متماثلة من كل انقسام. 3- الخلايا المتكونة متماثلة وراثياً / الخلايا الناتجة مختلفة وراثياً. 4- عدد الكروموسومات في الخليتين المتكونتين مماثل لعددها في الخلية الأم / عدد الكروموسومات في الخلايا الناتجة نصف العدد الموجود في الخلية الأم. 5- يحصل الانقسام في الخلايا الجسمية / يحصل الانقسام في الخلايا الجرثومية. 6- تحصل وتقام طوال حياة الكائن الحي / تحصل بعد مرحلة النضج الجنسي. 7- يشارك هذا الانقسام في النمو واصلاح التلف في الخلايا والتكاثر اللاجنسي / يشارك في التكاثر الجنسي ونقل المادة الوراثية من الآباء الى الأبناء.",
