      "o": [],
      "c": -1,
      "why": "1- تخلص سايتوبلازم الخلية من بعض الدقائق الغذائية وقطع المايتوكوندريا وبقايا الجسيمات الحالة وغيرها من الشوائب. 2- تؤدي الجسيمات الحالة دوراً مهماً في عملية التحول الشكلي في الحيوانات (على سبيل المثال اختفاء ذنب يرقات الضفادع عند تحولها إلى ضفادع بالغة)، وتتم هذه العملية من خلال تحرر الإنزيمات من الجسيمات الحالة إلى سايتوبلازم الخلية وينتج عن ذلك هضم محتويات السايتوبلازم من الجزيئات الكبيرة وبذلك تصبح الخلية مادة للتحلل الذاتي. 3- تعمل على تحطيم الخلايا المكونة لها عند موت الكائن الحي. 4- تدوير العناصر في الطبيعة من خلال عملية التحلل الذاتي.",
