      "why": "وهو سائل يتجمع من الانسجة ويرجع الىٰ بجرى الدم بوساطة أوعية لمفاوية ، ويشبه اللمف البلازما في التركيب الا أن محتواه البروتيني أقل وعملية التختر فيه تكون أبطأ والخثرة تكون لينة لاصلبة . ويحتوي اللمف علىٰ غلايا لمفية بالدرجة الرئيسة : وتختلف نسبتها تبعاً لعدد العقد اللمفية التي يمر فيها والتي تقع في طريق الاوعية اللمفية .",
