      "o": [],
      "c": -1,
      "why": "1- الغشاء البلازمي: طبقتين دقيقتين من الدهون المفسفرة وتتخلل الطبقتين جزيئات بروتينية. 2- السايتوبلازم: 80% ماء، والبروتينات 15%، وما تبقى 5% يتمثل بالشحوم والسكريات وأملاح متنوعة. 3- الخيوط الدقيقة: خيوط الاكتين المكونة من بروتين الاكتين وخيوط المايوسين المكونة من بروتين المايوسين. 4- جدار الخلية: بالنسبة لجدار خلية البكتيريا (البروتين والدهون وعديد السكريد)، وبالنسبة للخلية النباتية (السليلوز في الخلايا الفتية ويتثخن بإضافة الخشبين (اللكنين) في الخلايا المتقدمة في العمر).",
