      "q": "س٦: اشرح التكاثر اللاجنسي في البراميسيوم",
      "o": [],
      "c": -1,
      "why": "يتكاثر البراميسيوم لاجنسياً بالانقسام الثنائي المستعرض: 1. يبدأ الانقسام بانقسام النواة الصغيرة انقساماً اعتيادياً. 2. مع انقسام النواة الصغيرة إلى نواتين تتجه كل منهما إلى طرف متضاد من طرفي البراميسيوم، وفي نفس الوقت تستطيل النواة الكبيرة ويظهر برعم الفم الخلوي. 3. تنقسم النواة الكبيرة انقساماً مباشراً إلى نواتين وتتجهان إلى طرفي الخلية (البراميسيوم)، ويتكون أخدود فمي جديد وتظهر فجوتان متقلصتان جديدتان، كما يحصل تخصر في جسم البراميسيوم ليقود إلى الانقسام. 4. ينقسم البراميسيوم إلى براميسيومين بنويين (جديدين).",
