      "q": "س٦: ما نوع النسيج (لأربع) مما يأتي: 1. بطانة جسيمات مالبيجي، 2. الحبل السري، 3. المثانة البولية، 4. الكمثرى، 5. صيوان الأذن.",
      "o": [],
