      "why": "1. بطانة جسيمات مالبيجي: نسيج ظهاري حرشفي بسيط. 2. الحبل السري: نسيج ضام مخاطاني. 3. المثانة البولية: نسيج ظهاري متحول. 4. الكمثرى: نسيج سكلرنكيمي أو الخلايا الصخرية (الحجرية). 5. صيوان الأذن: نسيج ضام متخصص أو الغضروف المطاط. (ملاحظة: في النقطة الرابعة والخامسة، إذا ذكر الطالب أي من الجوابين يعطى درجة كاملة).",
