      "q": "س٥: أ) أجب عمّا يأتي : ( اثنين فقط ) ١) ما هي مكونات البويض الناضج في الزهرة ؟ ٢) تمثل الرموز الآتية تتابع النيوكليوتيدات في جزيئة الـ DNA : TAC GGT CTC AGC . أولاً : ما تتابع نسخة الـ mRNA الناتجة من التتابع أعلاه ؟ ثانياً : ما الكودونات المضادة في tRNA التي ترتبط بنسخة الـ mRNA أعلاه ؟ ٣) من هو أول عالم اعتمد التجربة في تفسير ظواهر التكوين الجنيني مع شرح تجربته ؟ ب) ارسم مع التأشير : ( تركيب البذرة ذوات الفلقتين ) . ج) اختر الجواب الصحيح لكل مما يأتي : ١) السايتوبلازم مادة معقدة نسبة البروتينا",
