      "q": "س٦: أ) احسب مقدار الطاقة المتحررة من أكسدة جزيء غرامي واحد من سكر الكلوكوز أكسدة تامة . ب) ما الطراز الوراثي ؟ (لثلاثة فقط ) لون الفراء في الأرنب فضي نقي ، العرف المفرد للدجاج ، طفل (+Rh) وأمّه (-Rh) ، شخص مصل دمه يحوي الجسم المضاد a وb . ج) اذكر مميزات كل مما يأتي : ( اثنين فقط ) مرحلة الحوصلة البدائية في الدورة المبيضية لأنثى الإنسان ، الطور الاستوائي الأول ، الغضروف الشفاف .",
