      "tid": "p12bioex320",
      "q": "س١: عرف ما يأتي: 2- الخلايا الدبقية، 5- مرحلة التنامي",
      "o": [],
      "c": -1,
      "why": "2- الخلايا الدبقية: وهي خلايا تشكل القسم الأعظم من النسيج العصبي حيث تكون نسبتها ضمن النسيج العصبي (50:1) أي كل عصبونة يقابلها 50 من خلايا الدبق العصبي وهي تشغل أكثر من نصف حجم الدماغ وتتلخص وظيفتها بإسناد الخلايا العصبية فضلاً عن كونها تبتلع البكتيريا والفتات الخلوي. 5- مرحلة التنامي: وهي إحدى مراحل دورة التحلل والإنتاج لتكاثر الفيروسات والتي يتم فيها اندماج الحامض النووي الفيروسي DNA مع الحامض النووي البكتيري DNA بدون أن يحصل تحطيم لـ DNA البكتيريا وعندئذ يسمى DNA الفيروس بالبلعم الأولي ويحصل تضاعف DNA الراشح مع تكاثر البكتيريا.",
