      "q": "س١: قارن بين اثنين مما يأتي: خصى الضفدع، مبايض الضفدع.",
      "o": [],
      "c": -1,
      "why": "1- الخصى: زوج من الخصى ملتصقة بالكلية. المبايض: زوج من المبايض يقعان قرب الكلية. 2- الخصى: تكون بشكل تركيب بيضوي متطاول. المبايض: تكون بشكل تركيب كيسي غير منتظم يظهر بشكل كيس متعدد الفصوص. 3- الخصى: لونها أصفر فامح. المبايض: لونها رصاصي مسود. 4- الخصى: ترتبط بجدار الجسم الداخلي بواسطة مسراق الخصية. المبايض: ترتبط بجدار الجسم الداخلي بواسطة مسراق المبيض. 5- الخصى: تحوي الخصية على نبيبات منوية ذات بطانة ظهارية تكون مسؤولة عن نشوء النطف بعملية تكوين النطف. المبايض: تنشأ البيوض من البطانة الظهارية الجرثومية المبطنة للمبيض من خلال عملية تكوين البيوض. 6- الخصى: يوجد في النهاية الأمامية للخصية أجسام دهنية. المبايض: يوجد في النهاية الأمامية للمبيض أجسام دهنية كما موجودة في الذكر.",
