      "c": -1,
      "why": "وزناً معيناً، أي بحر من بحور الشعر وهو ما يسمى موسيقا الشعر الذي يمثل الجزء المهم في بناء القصيدة فضلاً عن القافية وهي حرف الروي الذي ينتهي به البيت ثم تلتزم به القصيدة. أما المعنى فهو الفكرة والغرض الموحد.",
      "year": 2014,
      "role": "الدور الأول",
      "src": "ministerial-ocr"
