      "o": [],
      "c": -1,
      "why": "بما أن النص المستخرج هو عبارة عن جدول إجابات نموذجية، فإن الأسئلة الأصلية غير مكتملة في النص، ولكن الإجابات المذكورة هي: أ- إعراب 'ما' (اسم استفهام مبني على السكون في محل رفع مبتدأ تلاه شبه جملة). ب- سبب نفي الفعل بـ 'لما' (لأن الجملة فعلية مسبوقة بـ 'قد'). ج- استخراج المتقدم وحكمه وسببه (للفراق، جوازاً، لأن المبتدأ نكرة مخصصة بالوصف والخبر شبه جملة).",
      "year": 2014,
