      "tid": "p12arex298",
      "q": "س٤: ١- يؤمن نجلود الروح، بعد تحررها من الجسد، وفيها إيمان بعظمة الخالق بأسلوب واضح الفكر عذب الألفاظ رقيق الموسيقا، مع تنوع في القوافي وميل الى الاوزان الراقصة، وضح ذلك من خلال قصيدة سقوط ورق الشجر في الخريف. ٢- طبيعة التجربة الشعرية عند الشاعر تقترب من السرد الذي يعنى بذكر الاحداث الفعلية الواقعية، فالشاعر هنا لا يستطرد الى التفاصيل ولا ينصرف الى الوصف الخارجي، فهو هنا فيلسوف من فلاسفة الجمال، ينظر بعين الفنان الى مظاهر الوجود، فيرى الجمال في كل شيء ضمنا في الاشياء الميتة والاوراق المتساقطة.. (",
      "o": [],
      "c": -1,
