      "why": "1) لدلالته الرمزية عن الثورة والتضحية وهو شائع في الأدب الثوري.. ولأن وطنه فلسطين من البلدان التي تشتهر بزراعة هذه الزهرة الجميلة. 2) يستهل الشاعر قصيدته بمخاطبة امرأة ما غير واضحة المعالم ولم نعرف من هي؟ فقد تكون الحبيبة أو الزوجة أو كونها رمزاً للوطن أو الأهل أو الوطن نفسه، وهنا نراه يؤكد العلاقة الجدلية بين الوطن والمرأة وكلاهما مصباح للروح، وهذا يعني أن وجود المرأة بعيداً عن الوطن تعني عاطفة ناقصة، ووطن بلا امرأة يعني وطناً خالياً من علاقات التواصل والحب والدفء. 3) المقالة ليست طويلة، إذ تأتي في صفحة أو أكثر بقليل وذلك لأنها لا تتناول كل الأفكار والحقائق المتعلقة بموضوعها إنما تتناول جانباً أو زاوية محددة منه. 4) تأثيره لما يحتويه من عواطف جامحة ومشاعر جميلة، وأخيلة وأحلام وروح إنسانية وولع بالطبيعة.",
