      "why": "أولاً: مؤلفها (محمد علي الخفاجي). عناصر التغيير المنتظرة تتمثل بالكرسي الكبير متصدراً القاعة، يظل فارغاً طيلة العرض المسرحي في انتظار المنقذ الذي سيملؤه، وكذلك السيف المعلّق الذي ينتظر من يمتشقه، والحسين الجالس لدى أخيه هو الفارس المؤمل لإحداث التغيير في ذلك الواقع. ثانياً: (يقبل من الطالب خمسة أسطر من المسرحية): يا ابن أبي.. يا حيدري / يا ركن البيت الدافئ / حين نحدس الأيام البرد / يا فرح المحزون ويا زاد الوحشة / أين تسافر؟ / والدنيا تفتر على قرن شيطانة / إذ ينزع قرطيها الأقوى / ولئن سافرت / يستدرك / من للعدل إمام غيرك؟ / العالم ملوث الأدران / والزمن الأعمى يخبط منصره بعصاه / إذ تضرب قبل العجز الأعناق (تأخذه نوبة سعال) / الحسين (مهدئاً نجليه): حسبي ذلك يا ابن أبي حسبي ذلك / (يطرق قليلاً ثم يواصل): ما كان الكون يوماً في طرف التغيير / لولا الاستشهاد.",
