      "o": [],
      "c": -1,
      "why": "١. تنبئ قصيدة (أوراق الخريف) عن إيمانه بخلود الروح بعد تجردها من الجسد وفيها إيمان بعظمة الخالق والذات المتأملة. وتنتمي هذه القصيدة إلى الشعر الرومانسي بأجوائه وأسلوبه، وضح الأفكار، عذب الألفاظ، رقيق الموسيقى مع تنوع في القوافي وميل إلى الأوزان الراقصة. ٢. الأبيات: تناثري تناثري يا بريحة المطر يا مرقص الشمس ويا أرجوحة القمر يا أرغفة النيل ويا قيثارة السحر يا رمز فكر حائر ورسم روح ثائر يا ذكر مجد غابر قد عافك الشجر تناثري تناثري عودي إلى حضن الثرى وجددي الجذور وانسي جمالاً قد ذوى حاشاه لن يعود كم أزهرت من قبلك وكم ذوت ورود فلا تسي في ما جرى ولا تلومي القدر عودي إلى حضن الثرى",
