      "why": "تتلخص آراء جماعة الديوان بما يأتي: 1- الشعر تعبير عن الوجدان: ترى أن يكون الشاعر صادقاً في التعبير عن مشاعره، وآرائه، وشعره متصل بوجدان قائله، ومن ثم يعبر عن وجدان الناس، ولقد فصّل عبد الرحمن شكري ذلك في بيتي الشعر اللذين أثبتهما على غلاف ديوانه الأول (ضوء الفجر). 2- الدعوة إلى الوحدة العضوية في القصيدة فضلاً عن وحدة الموضوع. 3- تنويع القوافي في القصيدة الواحدة، والتجديد والتحرر من قيودها من دون الخروج عن عمودها التراثي. 4- الدعوة إلى التجديد في الصور الشعرية والأساليب واستعمال اللغة الواضحة.",
