      "why": "٣- عدم الالتزام بعدد محدد من التفعيلات كما هو شائع في البيت ذي الشطرين مع الالتزام بترتيبها. ٤- الغموض الشفاف مع شيء من الرمز واللغة الموحية. ٥- توظيف الأساطير والحكايات الخرافية والشعبية لتعميق الدلالة المعنوية. ٦- غياب الأغراض المألوفة كالمديح والهجاء والفخر وغيرها وإحلال مضامين جديدة. ٧- التقليل من شأن الغنائية والروح الرومانسية وإلغاء الخطابية واختفاء الشاعر وراء إبداعه في إطار لغة مهموسة.",
