      "q": "س٤: أ) شاعر عراقي رومانسي اشتغل بالصحافة بوصفه شاعراً وكاتباً للمقالة الأدبية دُفن في مقبرة الغرباء ، مَنْ الشاعر ؟ وما عنوان قصيدته ؟ اكتب له ثلاثة أبيات منها مضبوطة بالشكل . ب) أجب عن أولا أو ثانياً : أولا : ما المسرحية الشعرية ؟ وأين ظهرت ؟ ومتى انحسرت ؟ ثانيا\" : كيف عرف أدبنا العربي المقالة ؟ ومتى ؟ وبمَ تأثِّرت ؟ ج) ١) لمن مهدت مدرسة الإحياء ؟ وماذا اتخذت من شعرنا القديم ؟ ٢) عمّ تكشف حوارية النص في قصيدة الشاعر ( محمود درويش ) ؟",
