      "q": "س٥: أ) للجواهريّ قصيدة في منهجك ، ما عنوانها ؟ ثمّ مثّل له أبياتاً بالأفكار الأتية : - جمع أنواع السفر في صورة واحدة استمدّها من القديم . - يستعير شبهاً بالطير الذي يتخفّف في طيرانه من كلّ ما يثقله . - أشاد باللغة العربية الفصحى . ب) أجب عن أولاً أو ثانياً : أولاً : أين ظهرت أولى قصص القاص ( محمد خضير ) ؟ ثمّ اذكر ثلاث منها . ثانياً : كيف تطوّر الشعر الوجداني عند الأوربيين ؟ وما أشهر أنواعه ؟ وبمَ تأثَر ؟ ( وضَح ذلك ) . ج) ما هي أفكار قصيدة الشاعر (محمود سامي البارودي) ؟ وضّحها ، ثمّ اكتب له بيت",
